using System;using System.IO;using System.Reflection;
internal static class WindowsVaultKeyTest {
 [STAThread]static int Main(string[] args){string root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  var type=typeof(WindowsVault);var create=type.GetMethod("CreatePending",BindingFlags.Static|BindingFlags.NonPublic);var read=type.GetMethod("ReadSecret",BindingFlags.Static|BindingFlags.NonPublic);string path=Path.Combine(root,"pending");
  create.Invoke(null,new object[]{path});byte[] before=File.ReadAllBytes(path);string secret=(string)read.Invoke(null,new object[]{path});if(Convert.FromBase64String(secret).Length!=32)throw new Exception("Invalid random key.");
  bool refused=false;try{create.Invoke(null,new object[]{path});}catch(TargetInvocationException){refused=true;}if(!refused||Convert.ToBase64String(before)!=Convert.ToBase64String(File.ReadAllBytes(path))||Directory.GetFiles(root,"*.tmp").Length!=0)throw new Exception("Pending key overwrite or leftover partial publication.");
  string old=Path.Combine(root,"vault.json");byte[] oldBytes=new byte[]{17,42,99};File.WriteAllBytes(old,oldBytes);string archived=(string)type.GetMethod("ArchiveLegacy",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{old});if(File.Exists(old)||!File.Exists(archived)||Convert.ToBase64String(File.ReadAllBytes(archived))!=Convert.ToBase64String(oldBytes))throw new Exception("Legacy vault backup changed bytes.");
  string recoveryKey=Path.Combine(root,"recovery-key"),recoveryPending=recoveryKey+".pending";create.Invoke(null,new object[]{recoveryKey});create.Invoke(null,new object[]{recoveryPending});byte[] originalKey=File.ReadAllBytes(recoveryKey),expectedKey=File.ReadAllBytes(recoveryPending);string expectedSecret=(string)read.Invoke(null,new object[]{recoveryPending});int attempts=0;
  var recover=type.GetMethod("UnlockKnownKeys",BindingFlags.Static|BindingFlags.NonPublic);Func<string,System.Threading.Tasks.Task> attempt=secretValue=>{attempts++;if(secretValue!=expectedSecret)throw new IOException("vault_unlock_failed");return System.Threading.Tasks.Task.FromResult(0);};
  ((System.Threading.Tasks.Task)recover.Invoke(null,new object[]{recoveryKey,attempt})).GetAwaiter().GetResult();if(attempts!=2||File.Exists(recoveryPending)||Convert.ToBase64String(File.ReadAllBytes(recoveryKey))!=Convert.ToBase64String(expectedKey))throw new Exception("Pending key recovery failed.");string[] backups=Directory.GetFiles(root,"recovery-key.previous-*");if(backups.Length!=1||Convert.ToBase64String(File.ReadAllBytes(backups[0]))!=Convert.ToBase64String(originalKey))throw new Exception("Previous key backup changed.");
  string failedKey=Path.Combine(root,"failed-key");create.Invoke(null,new object[]{failedKey});create.Invoke(null,new object[]{failedKey+".pending"});byte[] failedBefore=File.ReadAllBytes(failedKey),pendingBefore=File.ReadAllBytes(failedKey+".pending");bool rejected=false;
  Func<string,System.Threading.Tasks.Task> fail=secretValue=>{throw new IOException("vault_unlock_failed");};try{((System.Threading.Tasks.Task)recover.Invoke(null,new object[]{failedKey,fail})).GetAwaiter().GetResult();}catch(IOException){rejected=true;}
  if(!rejected||Convert.ToBase64String(File.ReadAllBytes(failedKey))!=Convert.ToBase64String(failedBefore)||Convert.ToBase64String(File.ReadAllBytes(failedKey+".pending"))!=Convert.ToBase64String(pendingBefore))throw new Exception("Failed recovery changed keys.");
  if(UsbOwnerVerification.Verify(IntPtr.Zero,"Verify synthetic test").GetAwaiter().GetResult())throw new Exception("Verification accepted invalid owner.");
  Console.WriteLine("DPAPI key round-trip, atomic publication, non-overwrite, temporary-file cleanup and invalid-owner refusal passed. No real vault touched.");return 0;
 }catch(Exception e){Console.WriteLine(e.Message);return 1;}finally{Directory.Delete(root,true);}}
}
